func (t *retryTransport) shouldRetry(attempt int, req *http.Request, canReplayBody bool, resp *http.Response, err error, policy RetryPolicy) bool {
	if err != nil || resp == nil {
		return false
	}
	if attempt >= policy.MaxAttempts {
		return false
	}

	switch resp.StatusCode {
	case 429:
		return canReplayBody
	case 502, 503, 504:
		if !canReplayBody {
			return false
		}
		return policy.RetryAllMethods || isIdempotentMethod(req.Method)
	default:
		return false
	}
}

func (t *retryTransport) nextDelay(attempt int, resp *http.Response, policy RetryPolicy) time.Duration {
	if resp != nil && resp.StatusCode == 429 {
		if ra := parseRetryAfter(resp.Header.Get("Retry-After"), t.opts.now()); ra > 0 {
			if policy.MaxRetryAfter > 0 && ra > policy.MaxRetryAfter {
				ra = policy.MaxRetryAfter
			}
			return ra
		}
	}

	if policy.BaseDelay <= 0 {
		return 0
	}

	exp := float64(policy.BaseDelay) * math.Pow(2, float64(attempt-1))
	delay := time.Duration(exp)
	if delay > policy.MaxDelay {
		delay = policy.MaxDelay
	}
	return policy.Jitter(delay)
}

func isIdempotentMethod(method string) bool {
	switch method {
	case http.MethodGet, http.MethodHead, http.MethodPut, http.MethodDelete, http.MethodOptions, http.MethodTrace:
		return true
	default:
		return false
	}
}

func fullJitter(d time.Duration) time.Duration {
	if d <= 0 {
		return 0
	}
	// #nosec G404 -- Retry jitter only needs inexpensive non-cryptographic randomness.
	return time.Duration(rand.Int64N(int64(d)))
}

package pipedrive

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

type RawClient struct {
	baseURL    *url.URL
	httpClient *http.Client
}

func NewRawClient(baseURL string, httpClient *http.Client) (*RawClient, error) {
	if httpClient == nil {
		httpClient = http.DefaultClient
	}
	u, err := url.Parse(baseURL)
	if err != nil {
		return nil, fmt.Errorf("parse base url: %w", err)
	}
	if u.Scheme == "" || u.Host == "" {
		return nil, errors.New("base url must include scheme and host")
	}
	u.Path = strings.TrimSuffix(u.Path, "/")

	return &RawClient{
		baseURL:    u,
		httpClient: httpClient,
	}, nil
}

func (c *RawClient) Do(ctx context.Context, method, path string, query url.Values, body any, out any, opts ...RequestOption) error {
	if c == nil {
		return errors.New("nil RawClient")
	}

	ctx, editors := ApplyRequestOptions(ctx, opts...)

	u := *c.baseURL
	u.Path = strings.TrimSuffix(u.Path, "/") + "/" + strings.TrimPrefix(path, "/")
	if query != nil {
		q := u.Query()
		for k, vs := range query {
			for _, v := range vs {
				q.Add(k, v)
			}
		}
		u.RawQuery = q.Encode()
	}

	var reqBody io.Reader
	if body != nil {
		switch b := body.(type) {
		case io.Reader:
			reqBody = b
		default:
			buf, err := json.Marshal(b)
			if err != nil {
				return fmt.Errorf("encode json body: %w", err)
			}
			reqBody = bytes.NewReader(buf)
		}
	}

	req, err := http.NewRequestWithContext(ctx, method, u.String(), reqBody)
	if err != nil {
		return fmt.Errorf("build request: %w", err)
	}

	req.Header.Set("Accept", "application/json")
	if body != nil {
		if _, ok := body.(io.Reader); !ok {
			req.Header.Set("Content-Type", "application/json")
		}
	}

	for _, editor := range editors {
		if editor == nil {
			continue
		}
		if err := editor(ctx, req); err != nil {
			return err
		}
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)

