func TestRetryTransport_RetriesWhenBodyIsReadSeeker(t *testing.T) {
	t.Parallel()

	var attempts int
	var receivedBodies []string

	next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
		attempts++
		b, err := io.ReadAll(req.Body)
		if err != nil {
			return nil, err
		}
		_ = req.Body.Close()
		receivedBodies = append(receivedBodies, string(b))

		if attempts == 1 {
			return &http.Response{
				StatusCode: 429,
				Header:     make(http.Header),
				Body:       io.NopCloser(strings.NewReader(`{"error":"rate limited"}`)),
				Request:    req,
			}, nil
		}

		return &http.Response{
			StatusCode: 200,
			Header:     make(http.Header),
			Body:       io.NopCloser(strings.NewReader(`{"ok":true}`)),
			Request:    req,
		}, nil
	})

	rt := newRetryTransport(next, DefaultRetryPolicy(), retryTransportOptions{
		sleep: func(context.Context, time.Duration) error { return nil },
		now:   time.Now,
	})

	payload := "document content"
	// Create an io.ReadSeeker body wrapped in an io.ReadCloser to simulate an *os.File
	seeker := strings.NewReader(payload)
	type readSeekCloser struct {
		*strings.Reader
	}
	rsc := readSeekCloser{Reader: seeker}

	req, _ := http.NewRequestWithContext(context.Background(), http.MethodPost, "https://example.test", rsc)
	// Explicitly clear req.GetBody to verify retryTransport reconstructs it from io.ReadSeeker
	req.GetBody = nil

	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("RoundTrip error: %v", err)
	}
	_ = resp.Body.Close()

	if attempts != 2 {
		t.Fatalf("expected 2 attempts, got %d", attempts)
	}
	if len(receivedBodies) != 2 {
		t.Fatalf("expected 2 received bodies, got %d", len(receivedBodies))
	}
	for i, b := range receivedBodies {
		if b != payload {
			t.Fatalf("attempt %d received %q, expected %q", i+1, b, payload)
		}
	}
}

